selector_to_html = {"a[href=\"../../ducts/orifice/Orifice.html#pyskyfire.ducts.orifice.Orifice\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.Orifice\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.orifice.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Orifice</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">area</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">cd</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">hydraulic_diameter</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">length</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>A short restriction discharging into a large volume.</p><p class=\"rubric\">Notes</p><p>Use <a class=\"reference internal\" href=\"#pyskyfire.ducts.orifice.Orifice.circular\" title=\"pyskyfire.ducts.orifice.Orifice.circular\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">circular()</span></code></a>, <a class=\"reference internal\" href=\"#pyskyfire.ducts.orifice.Orifice.annular\" title=\"pyskyfire.ducts.orifice.Orifice.annular\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">annular()</span></code></a> or <a class=\"reference internal\" href=\"#pyskyfire.ducts.orifice.Orifice.slot\" title=\"pyskyfire.ducts.orifice.Orifice.slot\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">slot()</span></code></a> for those shapes.\nThe generic constructor takes any area, so an effective area quoted as\n<code class=\"docutils literal notranslate\"><span class=\"pre\">Cd\u00b7A</span></code> can be given as <code class=\"docutils literal notranslate\"><span class=\"pre\">Orifice(area=CdA,</span> <span class=\"pre\">cd=1.0)</span></code>.</p></dd>", "a[href=\"#pyskyfire-injector-injector-injector\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.injector.injector.Injector<a class=\"headerlink\" href=\"#pyskyfire-injector-injector-injector\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"#pyskyfire.injector.injector.Injector.checks\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.injector.Injector.checks\">\n<span class=\"sig-name descname\"><span class=\"pre\">checks</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">chamber_radius</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/constants.html#None\" title=\"(in Python v3.15)\"><span class=\"pre\">None</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"InjectorChecks.html#pyskyfire.injector.injector.InjectorChecks\" title=\"pyskyfire.injector.injector.InjectorChecks\"><span class=\"pre\">InjectorChecks</span></a></span></span></dt><dd><p>Layout checks: webs between holes, holes and targets against the wall, hole L/D.</p><p>Hole outlines on the face are taken as circles of the\n<code class=\"xref py py-attr docutils literal notranslate\"><span class=\"pre\">InjectorHoles.footprint</span></code> radius, which is conservative for an\ninclined hole\u2019s ellipse.</p></dd>", "a[href=\"#pyskyfire.injector.injector.Injector.equivalent_orifice\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.injector.Injector.equivalent_orifice\">\n<span class=\"sig-name descname\"><span class=\"pre\">equivalent_orifice</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">feed</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"../../ducts/orifice/Orifice.html#pyskyfire.ducts.orifice.Orifice\" title=\"pyskyfire.ducts.orifice.Orifice\"><span class=\"pre\">Orifice</span></a></span></span></dt><dd><p>One orifice with the summed area and <code class=\"docutils literal notranslate\"><span class=\"pre\">Cd\u00b7A</span></code> of every hole on <code class=\"docutils literal notranslate\"><span class=\"pre\">feed</span></code>.</p></dd>", "a[href=\"#pyskyfire.injector.injector.Injector.holes\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.injector.Injector.holes\">\n<span class=\"sig-name descname\"><span class=\"pre\">holes</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"InjectorHoles.html#pyskyfire.injector.injector.InjectorHoles\" title=\"pyskyfire.injector.injector.InjectorHoles\"><span class=\"pre\">InjectorHoles</span></a></span></span></dt><dd><p>Every hole, placed in the injector frame.</p></dd>", "a[href=\"#pyskyfire.injector.injector.Injector.solve\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.injector.Injector.solve\">\n<span class=\"sig-name descname\"><span class=\"pre\">solve</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">conditions</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/library/collections.abc.html#collections.abc.Mapping\" title=\"(in Python v3.15)\"><span class=\"pre\">Mapping</span></a></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_face</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">oxidizer</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">()</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"InjectorResult.html#pyskyfire.injector.injector.InjectorResult\" title=\"pyskyfire.injector.injector.InjectorResult\"><span class=\"pre\">InjectorResult</span></a></span></span></dt><dd><p>Every feed at its operating point, discharging into a face at <code class=\"docutils literal notranslate\"><span class=\"pre\">p_face</span></code>.</p></dd>", "a[href=\"InjectorHoles.html#pyskyfire.injector.injector.InjectorHoles\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.injector.InjectorHoles\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.injector.injector.</span></span><span class=\"sig-name descname\"><span class=\"pre\">InjectorHoles</span></span></dt><dd><p>Every hole of an injector, placed in the injector frame.</p><p>Arrays have one row per hole. <code class=\"docutils literal notranslate\"><span class=\"pre\">set_name</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">element_index</span></code> say\nwhich element a hole belongs to; <code class=\"docutils literal notranslate\"><span class=\"pre\">feeds</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">orifices</span></code> are tuples\naligned with them. <code class=\"docutils literal notranslate\"><span class=\"pre\">footprint</span></code> is the radius of the hole\u2019s outline on\nthe face [m]: half its diameter, stretched by the inclination.</p></dd>", "a[href=\"FeedResult.html#pyskyfire.injector.injector.FeedResult\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.injector.FeedResult\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.injector.injector.</span></span><span class=\"sig-name descname\"><span class=\"pre\">FeedResult</span></span></dt><dd><p>The flow through every hole on one feed.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">orifice</span></code> is the result for the feed\u2019s equivalent orifice: its inlet\nis the plenum and its outlet the face. <code class=\"docutils literal notranslate\"><span class=\"pre\">set_mass_flows</span></code> gives each\nelement set\u2019s share [kg/s]. <code class=\"docutils literal notranslate\"><span class=\"pre\">fluid</span></code> is the CoolProp name the feed\nran on, or None when its fluid named none.</p></dd>", "a[href=\"#pyskyfire.injector.injector.Injector.solve_feed\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.injector.Injector.solve_feed\">\n<span class=\"sig-name descname\"><span class=\"pre\">solve_feed</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">feed</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_state</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"../../thermo/state/FluidState.html#pyskyfire.thermo.state.FluidState\" title=\"pyskyfire.thermo.state.FluidState\"><span class=\"pre\">FluidState</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mass_flow</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fluid</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"FeedResult.html#pyskyfire.injector.injector.FeedResult\" title=\"pyskyfire.injector.injector.FeedResult\"><span class=\"pre\">FeedResult</span></a></span></span></dt><dd><p>The face pressure one feed reaches from its plenum at <code class=\"docutils literal notranslate\"><span class=\"pre\">mass_flow</span></code>.</p><p>The engine network\u2019s direction: see <code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">Orifice.solve()</span></code>.</p></dd>", "a[href=\"#pyskyfire.injector.injector.Injector.__repr__\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.injector.Injector.__repr__\">\n<span class=\"sig-name descname\"><span class=\"pre\">__repr__</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.injector.injector.Injector.feeds\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.injector.Injector.feeds\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">feeds</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#tuple\" title=\"(in Python v3.15)\"><span class=\"pre\">tuple</span></a></span></dt><dd><p>Every feed, in the order the sets first name them.</p></dd>", "a[href=\"#pyskyfire.injector.injector.Injector\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.injector.Injector\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.injector.injector.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Injector</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">element_sets</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Element sets on a face, and the hydraulics of the feeds that supply them.</p></dd>", "a[href=\"../../thermo/state/FluidState.html#pyskyfire.thermo.state.FluidState\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.state.FluidState\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.state.</span></span><span class=\"sig-name descname\"><span class=\"pre\">FluidState</span></span></dt><dd><p>Resolved bulk fluid state at one axial station.</p></dd>", "a[href=\"InjectorChecks.html#pyskyfire.injector.injector.InjectorChecks\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.injector.InjectorChecks\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.injector.injector.</span></span><span class=\"sig-name descname\"><span class=\"pre\">InjectorChecks</span></span></dt><dd><p>What the injector can check about its own layout, reported not enforced.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">min_web</span></code> is the narrowest ligament between two hole outlines on the\nface [m], between holes in sets <code class=\"docutils literal notranslate\"><span class=\"pre\">min_web_sets</span></code>; <code class=\"docutils literal notranslate\"><span class=\"pre\">overlaps</span></code> counts\npairs whose outlines intersect. <code class=\"docutils literal notranslate\"><span class=\"pre\">outer_radius</span></code> is how far the\noutermost hole outline reaches from the axis, and <code class=\"docutils literal notranslate\"><span class=\"pre\">target_radius</span></code> the\nfurthest any jet\u2019s target lies from it [m]. <code class=\"docutils literal notranslate\"><span class=\"pre\">wall_clearance</span></code> is the\nchamber radius less <code class=\"docutils literal notranslate\"><span class=\"pre\">outer_radius</span></code>: room between the holes and the\nwall. <code class=\"docutils literal notranslate\"><span class=\"pre\">target_clearance</span></code> is the chamber radius less <code class=\"docutils literal notranslate\"><span class=\"pre\">target_radius</span></code>:\nzero where a jet is aimed at the wall on purpose, as a film-cooling jet\nis, and negative where a target lies beyond it. Both are NaN without a\nchamber radius. <code class=\"docutils literal notranslate\"><span class=\"pre\">min_length_to_diameter</span></code> is the shortest hole relative\nto its diameter.</p></dd>", "a[href=\"#pyskyfire.injector.injector.Injector._feed_result\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.injector.Injector._feed_result\">\n<span class=\"sig-name descname\"><span class=\"pre\">_feed_result</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">feed</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">orifice_result</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fluid</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"FeedResult.html#pyskyfire.injector.injector.FeedResult\" title=\"pyskyfire.injector.injector.FeedResult\"><span class=\"pre\">FeedResult</span></a></span></span></dt><dd></dd>", "a[href=\"#pyskyfire.injector.injector.Injector.hole_count\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.injector.Injector.hole_count\">\n<span class=\"sig-name descname\"><span class=\"pre\">hole_count</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">feed</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#int\" title=\"(in Python v3.15)\"><span class=\"pre\">int</span></a></span></span></dt><dd><p>Number of holes on <code class=\"docutils literal notranslate\"><span class=\"pre\">feed</span></code>.</p></dd>", "a[href=\"#pyskyfire.injector.injector.Injector._check_feed\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.injector.Injector._check_feed\">\n<span class=\"sig-name descname\"><span class=\"pre\">_check_feed</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">feed</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"InjectorResult.html#pyskyfire.injector.injector.InjectorResult\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.injector.InjectorResult\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.injector.injector.</span></span><span class=\"sig-name descname\"><span class=\"pre\">InjectorResult</span></span></dt><dd><p>Every feed and set at one operating point, into a face at <code class=\"docutils literal notranslate\"><span class=\"pre\">p_face</span></code>.</p></dd>", "a[href=\"#pyskyfire.injector.injector.Injector.sets\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.injector.Injector.sets\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">sets</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#dict\" title=\"(in Python v3.15)\"><span class=\"pre\">dict</span></a></span></dt><dd><p>Element sets by name.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
